'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let index = 0;
const L = input[index++];
const C = input[index++];
const P = input[index++];

const black = Array.from({ length: L }, () => Array(C).fill(false));
for (let i = 0; i < P; i++) {
  const x = input[index++] - 1;
  const y = input[index++] - 1;
  black[x][y] = true;
}

const eligible = Array.from({ length: L }, () => Array(C).fill(false));
const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (black[r][c]) continue;
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
        eligible[r][c] = true;
        break;
      }
    }
  }
}

const leftCells = [];
const rightId = Array.from({ length: L }, () => Array(C).fill(-1));
let vertexCount = 0;

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (!eligible[r][c]) continue;
    vertexCount++;
    if ((r + c) % 2 === 0) leftCells.push([r, c]);
    else rightId[r][c] = vertexCount - 1;
  }
}

const matchRight = Array(L * C).fill(-1);
const adjacency = leftCells.map(([r, c]) => {
  const neighbors = [];
  for (const [dr, dc] of directions) {
    const nr = r + dr;
    const nc = c + dc;
    if (nr >= 0 && nr < L && nc >= 0 && nc < C && eligible[nr][nc]) {
      neighbors.push(nr * C + nc);
    }
  }
  return neighbors;
});

function augment(u, seen) {
  for (const v of adjacency[u]) {
    if (seen[v]) continue;
    seen[v] = true;
    if (matchRight[v] === -1 || augment(matchRight[v], seen)) {
      matchRight[v] = u;
      return true;
    }
  }
  return false;
}

let matching = 0;
for (let u = 0; u < leftCells.length; u++) {
  if (augment(u, Array(L * C).fill(false))) matching++;
}

console.log(vertexCount - matching);
